// Sort keys for the second level of a browse — what is inside a row (`ardBrowse(childOrder:)`). Grouped by name those are versions; a future facet-backed type brings its own next level, which is why this is not spelled "version". Distinct from `ArdBrowseSort`, which ranks the rows: NAME and VERSION_COUNT mean nothing for a single version, and VERSION means nothing for a name that has many. A key that cannot be answered would sort nothing while looking like it worked. There is no RISK_CATEGORY key — a version carries exactly one worst score, so bucketing it into a rating would only create ties with no secondary key to break them.
const (
	ArdBrowseChildSortVersion    ArdBrowseChildSort = "VERSION"     // Version order — epoch, then release, then prerelease-vs-revision — and NOT lexical: `9.0` is below `16.0`, `-r4` below `-r10`, and a distro revision is newer than the release it packages while `-rc1` is older. ASC = oldest first.
	ArdBrowseChildSortAssetCount ArdBrowseChildSort = "ASSET_COUNT" // Distinct in-scope assets carrying that exact version.
	ArdBrowseChildSortScore      ArdBrowseChildSort = "SCORE"       // The child's aggregate risk — the worst score across the assets carrying it (riskValue, higher = worse). DESC = most at risk first; a version no asset has a score for ranks last either way rather than leading the ascending page.
)

// ArdBrowseSort represents sort keys for `ardBrowse`. Pair with `sortDir` (default ascending).
type ArdBrowseSort string

// Sort keys for `ardBrowse`. Pair with `sortDir` (default ascending).
const (
	ArdBrowseSortName         ArdBrowseSort = "NAME"          // Product name (the default; the stable tiebreaker for every other key).
	ArdBrowseSortAssetCount   ArdBrowseSort = "ASSET_COUNT"   // Distinct in-scope assets carrying the name.
	ArdBrowseSortScore        ArdBrowseSort = "SCORE"         // Worst score across the name's versions (riskValue, higher = worse). DESC = most at risk first; names with no score sort last either way.
	ArdBrowseSortFreshness    ArdBrowseSort = "FRESHNESS"     // Freshness marker (reserved; populated in a follow-up).
	ArdBrowseSortVersionCount ArdBrowseSort = "VERSION_COUNT" // Distinct in-scope versions of the name.
	ArdBrowseSortRiskCategory ArdBrowseSort = "RISK_CATEGORY" // Discretized risk rating (critical / high / medium / low / none) instead of the raw worst score, so a `thenBy` key can meaningfully break ties within a rating. DESC = most critical rating first; names with no score sort last either way. The `ArdEntityOrderField` twin is RISK_CATEGORY, and the two rank identically.
)

// ArdEntityKind represents the shape of an ARD entity — which of the three row kinds it is. `kind`, NOT `grouping`, is what tells a terminal resource from a navigational node: LEAF and SPINE both report `grouping: null` because both are grouping-independent.
type ArdEntityKind string

// The shape of an ARD entity — which of the three row kinds it is. `kind`, NOT `grouping`, is what tells a terminal resource from a navigational node: LEAF and SPINE both report `grouping: null` because both are grouping-independent.
const (
	ArdEntityKindLeaf   ArdEntityKind = "LEAF"   // A resource identified by its full dimensions, shared across every grouping. The terminal "real thing" — it has no children to drill into. Filter on `kind == LEAF` to get the actual resources out of a mixed listing.
	ArdEntityKindSpine  ArdEntityKind = "SPINE"  // A grouping-INDEPENDENT shared inventory node (name / version), shared by every lens in the same family. Navigational and addressable: pass its `mrn` to `ardEntity` or as `parentMrn` to drill down.
	ArdEntityKindBucket ArdEntityKind = "BUCKET" // A lens-specific navigational prefix within one grouping (e.g. a vendor or category bucket under `by-vendor`). Addressable like a spine node, but only within its own grouping.
)

// ArdEntityOrderField represents fields an ARD entity listing can be ordered by.
type ArdEntityOrderField string

// Fields an ARD entity listing can be ordered by.
const (
	ArdEntityOrderFieldName         ArdEntityOrderField = "NAME"
	ArdEntityOrderFieldScore        ArdEntityOrderField = "SCORE" // Raw risk score. DESC = most at risk first; unscored entities sort last either way.
	ArdEntityOrderFieldAssetCount   ArdEntityOrderField = "ASSET_COUNT"
	ArdEntityOrderFieldRiskCategory ArdEntityOrderField = "RISK_CATEGORY" // Discretized risk rating (critical / high / medium / low / none) instead of the raw score, so a `thenBy` key can meaningfully break ties within a rating. DESC = most critical rating first; unscored entities sort last either way.
	ArdEntityOrderFieldCost         ArdEntityOrderField = "COST"          // Rolled-up llm-model spend (ArdAggregation.modelUsageStats.costMicroUsd). DESC = most expensive first. An entity with no reported usage ranks as 0 — it stays in the page, at the bottom. Meaningful only for `type: "llm-model"`.
	ArdEntityOrderFieldTotalTokens  ArdEntityOrderField = "TOTAL_TOKENS"  // Rolled-up llm-model token volume: input + output + cache-read + cache-creation (web search requests are not tokens and are excluded). DESC = heaviest first; no reported usage ranks as 0. Meaningful only for `type: "llm-model"`.
	ArdEntityOrderFieldVersion      ArdEntityOrderField = "VERSION"       // Version order over the entity's `version` dimension — epoch, then release, then prerelease-vs-revision, never lexical. ASC = oldest first. For listing one product's versions (`ArdEntity.children` of a name node); an entity with no version ranks below every version.
)

